import{_ as l,l as i,o as e,c as o,v as t,p as d,x as r,d as s,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"可转债市场结构","description":"","frontmatter":{"title":"可转债市场结构","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-convertible-market.md","filePath":"quant/cn-convertible-market.md","lastUpdated":1789023840000}'),h={name:"quant/cn-convertible-market.md"};function p(A,a,u,B,m,_){const n=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="可转债市场结构" tabindex="-1">可转债市场结构 <a class="header-anchor" href="#可转债市场结构" aria-label="Permalink to &quot;可转债市场结构&quot;">​</a></h1><div class="epigraph"><p>A 股可转债是「债券 + 转股权 + 下修与赎回条款」在交易所竞价；T+0、涨跌停与正股 T+1 不对称，使联立对冲变成制度问题，而不只是模型 delta。</p><footer>—— 沪深交易所可转换公司债券交易规则与上市规则相关条款；Mitchell, Pedersen and Pulvino, Slow Moving Capital, AER, 2007；对照[可转债套利](/quant/convertible-arb)</footer></div><p><a href="/quant/cn-commodity-options">上一课</a>停在商品波动率。本课回到交易所信用–权益混合。<a href="/quant/convertible-arb">可转债套利</a> 已写 delta 对冲与慢资本；<a href="/quant/convertible-credit">转债信用</a> 写定价核。本课的缺口是<strong>A 股市场结构</strong>：竞价、涨跌停、转股、下修、强赎、与正股 T+1 / 融券约束如何改写可交易带。后课北交所换一层公司宇宙。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>国际转债套利假设正股可连续卖空、转债与正股同步交易。A 股：转债多数可当日回转，正股 T+1；正股涨跌停 10% 或 20%，转债涨跌停幅度不同（历史上与现行规则以交易所公告为准，回测须分段）；融券正股受标的与券源限制。于是「便宜凸性」可能无法对冲，或只能用期货对冲 beta，留下特异风险。问题是把可交易集写成：条款模型价 − 市价 − 对冲摩擦（涨跌停、T+1、借券、冲击）。摩擦大于折价则不是套利，是风险溢价或不可执行。</p><p>下修、强赎、回售是发行人与持有人的博弈，公告窗口伴随停牌，见<a href="/quant/cn-halt-resume">停复牌</a>。用连续 delta 对冲穿过停牌，路径非法。转股形成的股票仍受 T+1，当日转股当日卖出的可行性以规则为准，不得假设。</p><h3 id="流动性与投资者结构" tabindex="-1">流动性与投资者结构 <a class="header-anchor" href="#流动性与投资者结构" aria-label="Permalink to &quot;流动性与投资者结构&quot;">​</a></h3><p>转债投资者含公募、私募、银行理财与散户，流动性在条款博弈日集中。平价附近换手高，深虚值更像信用债。容量按转债 ADV 与正股可空量的最小计。2017–2021 供给扩张与 2024 年监管与定价环境变化，使样本不可当成单一制度。</p><p><span class="marginnote">转债在交易所竞价，不是银行间信用债。估值用交易所成交，不要用中债估值去填可交易价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条款引擎：转股价、下修触发、赎回触发、回售、修正后转股价。市场数据：转债竞价、正股竞价、停牌与涨跌停状态。对冲：优先正股融券（若在可行集），否则行业期货或 ETF，并报告残差。回测在正股涨停时停止买入对冲腿、跌停时停止卖出，转债腿按自身停板。事件：下修/强赎公告日用公告时点，不用财报日。</p><p>与<a href="/quant/cn-public-quant">指增</a>：公募持有转债的比例与估值方法受产品规则约束，不能把对冲基金式杠杆转债套利写进公募指增。</p><h3 id="信用与权益因子拆开" tabindex="-1">信用与权益因子拆开 <a class="header-anchor" href="#信用与权益因子拆开" aria-label="Permalink to &quot;信用与权益因子拆开&quot;">​</a></h3><p>平价低时信用利差主导，应用信用研究方法；平价高时看权益波动与下修期权。混合样本的单一「转债因子」没有对象。Mitchell 等慢资本在 A 股对应：条款博弈日拥挤、融资与正股停牌使折价持续。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不对称交易规则制造结构性错误定价带：可以看见、不能锁。带的宽度随融券政策与涨跌停而变。2015 年正股跌停、转债仍交易（或相反，视当时规则），对冲缺口放大。这是微观结构，不是 BS 隐含波动「算错」。</p><p>转股稀释与下修改变有效行权价，路径依赖强。模型必须用当时有效转股价，点-in-time 条款与会计 vintage 同纪律。</p>',17)),(e(),d(E,null,{default:r(()=>[c(n,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20CB%5B%22%E8%BD%AC%E5%80%BA%E7%AB%9E%E4%BB%B7%20%E5%A4%9A%E5%8F%AF%20T%2B0%22%5D%20--%3E%20Spread%5B%22%E6%8A%98%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20Eq%5B%22%E6%AD%A3%E8%82%A1%20T%2B1%20%E6%B6%A8%E8%B7%8C%E5%81%9C%22%5D%20--%3E%20Hedge%5B%22%E5%AF%B9%E5%86%B2%E5%8F%AF%E8%A1%8C%E9%9B%86%22%5D%0A%20%20Lend%5B%22%E8%9E%8D%E5%88%B8%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20Hedge%0A%20%20Hedge%20--%3E%20Exec%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E5%B8%A6%22%5D%0A%20%20Spread%20--%3E%20Exec%0A%20%20Call%5B%22%E5%BC%BA%E8%B5%8E%E4%B8%8B%E4%BF%AE%E5%81%9C%E7%89%8C%22%5D%20--%3E%20Exec%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用未公开下修信息、或在停牌规则边缘阻碍投资者交易的方法。可交换债、分离交易可转债条款不同。银行间转债极少，本课对象是交易所可转债。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>A 股转债的可交易带由 T+0/T+1 不对称、涨跌停与融券共同决定。</li><li>对冲残差必须报告；条款须点-in-time。</li><li>容量取转债流动性与正股可空的最小。</li><li>出处：沪深转债交易与上市规则；Mitchell, Pedersen and Pulvino, <em>AER</em>, 2007。</li></ul>',4))])}const f=l(h,[["render",p]]);export{q as __pageData,f as default};
